"""Replaces the S@Learn promotion's logo with the real one the owner
provided (2026-09-11, second version — a cleaner transparent-background
3D logo). Resized to 256x256 before embedding (the original was a
910KB/1000x1000 source image; this only ever renders at a small icon
size in the app) so this migration stays a reasonable size."""

import base64

from django.core.files.base import ContentFile
from django.db import migrations

_LOGO_B64 = (
    ""
)


def update_logo(apps, schema_editor):
    # No separate "delete the old file" step: AWS_S3_FILE_OVERWRITE is
    # effectively on for this bucket (confirmed live — a second save() to
    # the same computed name replaces the existing object's bytes in
    # place, it never gets a random-suffixed alternate name the way it
    # would under uniquify-on-collision behavior). save() below already
    # is the full replace; a prior version of this migration also called
    # old_logo.delete() afterward, which — since FieldFile.save() mutates
    # the same field-file object in place rather than returning a new one
    # — ended up deleting the file this same call had just uploaded.
    Promotion = apps.get_model("promotions", "Promotion")
    promo = Promotion.objects.filter(sponsor_name="S@Learn").first()
    if promo is None:
        return
    promo.logo.save("slearn_logo.png", ContentFile(base64.b64decode(_LOGO_B64)), save=True)


def noop_reverse(apps, schema_editor):
    # The previous logo's bytes aren't kept anywhere to restore — this
    # migration is a one-way content update, same as any other real data
    # fix. Reversing just leaves the newer logo in place.
    pass


class Migration(migrations.Migration):
    dependencies = [("promotions", "0003_seed_slearn_promotion")]
    operations = [migrations.RunPython(update_logo, noop_reverse)]
